import React, { useState } from 'react';
import { gql, useQuery, useMutation } from '@apollo/client';

// ============================================================
// HELPER
// ============================================================
function formatDuration(seconds) {
  if (!seconds && seconds !== 0) return '—';
  const m = Math.floor(seconds / 60);
  const s = String(seconds % 60).padStart(2, '0');
  return `${m}:${s}`;
}

// ============================================================
// QUERIES & MUTATIONS
// ============================================================
const TRACKS_QUERY = gql`
  query Tracks($page: Int, $limit: Int) {
    tracks(page: $page, limit: $limit) {
      nodes {
        id
        title
        link
        cover_medium
        album { id title }
        artist { id name }
        duration
        rank
        explicit_lyrics
        position
        preview
      }
      totalCount
      pageInfo {
        hasNextPage
        hasPreviousPage
        currentPage
        totalPages
      }
    }
  }
`;

const TOP_TRACKS_QUERY = gql`
  query TopTracks($limit: Int) {
    topTracks(limit: $limit) {
      id
      title
      rank
      artist { name }
    }
  }
`;

// Récupère les IDs des pistes likées par l'utilisateur connecté
const LIKED_TRACKS_QUERY = gql`
  query LikedTracks {
    likedTracks {
      id
    }
  }
`;

const CREATE_TRACK_MUTATION = gql`
  mutation CreateTrack($input: CreateTrackInput!) {
    createTrack(input: $input) {
      id
      title
    }
  }
`;

const DELETE_TRACK_MUTATION = gql`
  mutation DeleteTrack($id: ID!) {
    deleteTrack(id: $id) {
      success
    }
  }
`;

const LIKE_TRACK_MUTATION = gql`
  mutation LikeTrack($trackId: ID!) {
    likeTrack(trackId: $trackId) {
      id
      track { id }
    }
  }
`;

const UNLIKE_TRACK_MUTATION = gql`
  mutation UnlikeTrack($trackId: ID!) {
    unlikeTrack(trackId: $trackId) {
      success
    }
  }
`;

const ALBUMS_LIST_QUERY = gql`
  query Albums {
    albums(limit: 100) {
      nodes {
        id
        title
        artist { id name }
      }
    }
  }
`;

// ============================================================
// COMPOSANT
// ============================================================
export default function Tracks({ token, userRole }) {
  const [page, setPage]                   = useState(1);
  const [showForm, setShowForm]           = useState(false);
  const [showTopTracks, setShowTopTracks] = useState(false);
  const [formData, setFormData]           = useState({
    title: '', albumId: '', artistId: '', duration: '',
    position: '', explicit_lyrics: false, rank: '', preview: '', link: '',
  });
  const [error, setError]     = useState('');
  const [success, setSuccess] = useState('');

  const authHeaders = { context: { headers: { authorization: `Bearer ${token}` } } };

  const { data, loading, error: queryError, refetch } = useQuery(TRACKS_QUERY, {
    variables: { page, limit: 6 },
    ...authHeaders,
  });

  const { data: topTracksData } = useQuery(TOP_TRACKS_QUERY, {
    variables: { limit: 10 },
    skip: !showTopTracks,
    ...authHeaders,
  });

  const { data: likedData, refetch: refetchLiked } = useQuery(LIKED_TRACKS_QUERY, {
    ...authHeaders,
    // skip si pas de token (non connecté)
    skip: !token,
  });

  const { data: albumsData } = useQuery(ALBUMS_LIST_QUERY, authHeaders);

  const [createTrack, { loading: createLoading }] = useMutation(CREATE_TRACK_MUTATION, {
    ...authHeaders,
    onCompleted: () => {
      setSuccess('Piste créée !');
      setFormData({
        title: '', albumId: '', artistId: '', duration: '',
        position: '', explicit_lyrics: false, rank: '', preview: '', link: '',
      });
      setShowForm(false);
      refetch();
    },
    onError: (err) => setError(err.message),
  });

  const [deleteTrack] = useMutation(DELETE_TRACK_MUTATION, {
    ...authHeaders,
    onCompleted: () => { setSuccess('Piste supprimée !'); refetch(); },
    onError: (err) => setError(err.message),
  });

  const [likeTrack] = useMutation(LIKE_TRACK_MUTATION, {
    ...authHeaders,
    onCompleted: () => { refetchLiked(); },
    onError: (err) => setError(err.message),
  });

  const [unlikeTrack] = useMutation(UNLIKE_TRACK_MUTATION, {
    ...authHeaders,
    onCompleted: () => { refetchLiked(); },
    onError: (err) => setError(err.message),
  });

  // Set des IDs likés pour lookup O(1)
  const likedIds = new Set((likedData?.likedTracks || []).map((t) => t.id));

  const handleLikeToggle = (track) => {
    if (likedIds.has(track.id)) {
      unlikeTrack({ variables: { trackId: track.id } });
    } else {
      likeTrack({ variables: { trackId: track.id } });
    }
  };

  const handleAlbumChange = (albumId) => {
    const album = albumsData?.albums?.nodes?.find((a) => a.id === albumId);
    setFormData({ ...formData, albumId, artistId: album?.artist?.id || '' });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    createTrack({
      variables: {
        input: {
          title:           formData.title,
          albumId:         formData.albumId,
          artistId:        formData.artistId,
          duration:        formData.duration  ? parseInt(formData.duration,  10) : undefined,
          position:        formData.position  ? parseInt(formData.position,  10) : undefined,
          rank:            formData.rank      ? parseInt(formData.rank,      10) : undefined,
          explicit_lyrics: formData.explicit_lyrics,
          preview:         formData.preview   || undefined,
          link:            formData.link      || undefined,
        },
      },
    });
  };

  if (loading)    return <div className="loading">⏳ Chargement des pistes...</div>;
  if (queryError) return <div className="error">❌ Erreur : {queryError.message}</div>;

  const tracks    = data?.tracks?.nodes    || [];
  const pageInfo  = data?.tracks?.pageInfo || {};
  const topTracks = topTracksData?.topTracks || [];

  return (
    <div>
      <h2>🎵 Pistes</h2>

      {error   && <div className="error">{error}</div>}
      {success && <div className="success">{success}</div>}

      {/* Barre d'actions */}
      <div className="filter-section">
        <button onClick={() => setShowTopTracks(!showTopTracks)} className="btn-primary">
          {showTopTracks ? '❌ Masquer' : '🏆 Top Pistes'}
        </button>

        {userRole === 'admin' && (
          <button
            onClick={() => setShowForm(!showForm)}
            className="btn-primary"
            style={{ marginLeft: '0.5rem' }}
          >
            {showForm ? '❌ Annuler' : '➕ Créer'}
          </button>
        )}

        {/* Top Tracks */}
        {showTopTracks && (
          <div style={{ marginTop: '1rem', background: '#f5f5f5', padding: '1rem', borderRadius: '4px' }}>
            <h4>Top 10 par rang</h4>
            {topTracks.map((track, idx) => (
              <div
                key={track.id}
                style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', padding: '0.5rem', borderBottom: '1px solid #ddd' }}
              >
                <span style={{ color: '#999', minWidth: 20, textAlign: 'right' }}>{idx + 1}</span>
                <strong style={{ flex: 1 }}>{track.title}</strong>
                <span style={{ color: '#999', fontSize: 13 }}>{track.artist?.name}</span>
                <span style={{ color: '#999', fontSize: 13 }}>★ {track.rank?.toLocaleString('fr-FR') ?? '—'}</span>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Formulaire création */}
      {userRole === 'admin' && showForm && (
        <div className="filter-section">
          <h4>Créer une piste</h4>
          <form onSubmit={handleSubmit}>
            <div className="filter-group">
              <div className="form-group">
                <label>Titre *</label>
                <input
                  type="text"
                  value={formData.title}
                  onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                  required
                />
              </div>
              <div className="form-group">
                <label>Album *</label>
                <select
                  value={formData.albumId}
                  onChange={(e) => handleAlbumChange(e.target.value)}
                  required
                >
                  <option value="">Sélectionner</option>
                  {albumsData?.albums?.nodes?.map((album) => (
                    <option key={album.id} value={album.id}>
                      {album.title} — {album.artist?.name}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            {formData.artistId && (
              <div className="form-group">
                <label>Artiste (déduit de l'album)</label>
                <input
                  type="text"
                  value={
                    albumsData?.albums?.nodes?.find((a) => a.artist?.id === formData.artistId)?.artist?.name || formData.artistId
                  }
                  readOnly
                  style={{ background: '#f0f0f0', cursor: 'not-allowed' }}
                />
              </div>
            )}

            <div className="filter-group">
              <div className="form-group">
                <label>Durée (secondes)</label>
                <input type="number" min="0" value={formData.duration}
                  onChange={(e) => setFormData({ ...formData, duration: e.target.value })}
                  placeholder="ex: 214" />
              </div>
              <div className="form-group">
                <label>Position dans l'album</label>
                <input type="number" min="1" value={formData.position}
                  onChange={(e) => setFormData({ ...formData, position: e.target.value })}
                  placeholder="ex: 3" />
              </div>
              <div className="form-group">
                <label>Rang (popularité)</label>
                <input type="number" min="0" value={formData.rank}
                  onChange={(e) => setFormData({ ...formData, rank: e.target.value })}
                  placeholder="ex: 850000" />
              </div>
            </div>

            <div className="filter-group">
              <div className="form-group">
                <label>URL Preview (30s)</label>
                <input type="url" value={formData.preview}
                  onChange={(e) => setFormData({ ...formData, preview: e.target.value })}
                  placeholder="https://..." />
              </div>
              <div className="form-group">
                <label>Lien Deezer</label>
                <input type="url" value={formData.link}
                  onChange={(e) => setFormData({ ...formData, link: e.target.value })}
                  placeholder="https://www.deezer.com/track/..." />
              </div>
            </div>

            <div className="form-group" style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <input
                type="checkbox"
                id="explicit_lyrics"
                checked={formData.explicit_lyrics}
                onChange={(e) => setFormData({ ...formData, explicit_lyrics: e.target.checked })}
              />
              <label htmlFor="explicit_lyrics" style={{ margin: 0 }}>Contenu explicite</label>
            </div>

            <button type="submit" className="btn-success" disabled={createLoading}>
              {createLoading ? '⏳ Création...' : '✅ Créer'}
            </button>
          </form>
        </div>
      )}

      {/* Liste des pistes */}
      <div className="items-grid">
        {tracks.map((track) => {
          const isLiked = likedIds.has(track.id);
          return (
            <div key={track.id} className="card">
              {/* Album cover */}
              {track.cover_medium && (
                <img
                  src={track.cover_medium}
                  alt={track.title}
                  style={{ width: '100%', borderRadius: '4px', marginBottom: '0.5rem', objectFit: 'cover', height: 140 }}
                />
              )}

              <h3>
                {track.explicit_lyrics && (
                  <span style={{
                    background: '#FCEBEB', color: '#A32D2D',
                    fontSize: 10, fontWeight: 600, padding: '1px 6px',
                    borderRadius: 3, marginRight: 6, verticalAlign: 'middle',
                  }}>E</span>
                )}
                {track.title}
              </h3>
              <p>🎤 {track.artist?.name}</p>
              <p>💿 {track.album?.title}</p>

              <div className="card-meta">
                {track.position && <span>#{track.position}</span>}
                <span>⏱️ {formatDuration(track.duration)}</span>
                {track.rank && <span>★ {track.rank.toLocaleString('fr-FR')}</span>}
              </div>

              {track.preview && (
                <audio controls src={track.preview}
                  style={{ width: '100%', marginTop: '0.5rem', height: 32 }} />
              )}

              {track.link && (
                <a href={track.link} target="_blank" rel="noreferrer"
                  style={{ display: 'inline-block', marginTop: '0.5rem', fontSize: 12, color: '#a020f0' }}>
                  🔗 Voir sur Deezer
                </a>
              )}

              {/* Actions : like + suppression */}
              <div className="card-actions" style={{ display: 'flex', gap: '0.5rem', marginTop: '0.5rem' }}>
                {/* Bouton like — visible pour tous les utilisateurs connectés */}
                {token && (
                  <button
                    onClick={() => handleLikeToggle(track)}
                    title={isLiked ? 'Retirer des favoris' : 'Ajouter aux favoris'}
                    style={{
                      background: isLiked ? '#fff0f5' : '#f5f5f5',
                      border: `1px solid ${isLiked ? '#e75480' : '#ddd'}`,
                      borderRadius: '6px',
                      padding: '4px 10px',
                      cursor: 'pointer',
                      fontSize: 16,
                      color: isLiked ? '#e75480' : '#999',
                      transition: 'all 0.15s ease',
                      flexShrink: 0,
                    }}
                  >
                    {isLiked ? '❤️' : '🤍'}
                  </button>
                )}

                {userRole === 'admin' && (
                  <button
                    onClick={() => {
                      if (window.confirm(`Supprimer "${track.title}" ?`))
                        deleteTrack({ variables: { id: track.id } });
                    }}
                    className="btn-danger"
                  >
                    🗑️ Supprimer
                  </button>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {tracks.length === 0 && <div className="empty">📭 Aucune piste</div>}

      <div style={{ display: 'flex', gap: '1rem', justifyContent: 'center', marginTop: '2rem' }}>
        <button
          onClick={() => setPage((p) => p - 1)}
          disabled={!pageInfo.hasPreviousPage}
          className="btn-secondary"
        >
          ← Précédent
        </button>
        <span style={{ alignSelf: 'center' }}>
          Page {pageInfo.currentPage} / {pageInfo.totalPages}
        </span>
        <button
          onClick={() => setPage((p) => p + 1)}
          disabled={!pageInfo.hasNextPage}
          className="btn-secondary"
        >
          Suivant →
        </button>
      </div>
    </div>
  );
}
